<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api} from '../lib/api';import {money,type Plan} from '../lib/commercial';import Icon from './Icon.vue';import Modal from './ui/Modal.vue';
const props=defineProps<{workspace:string;sample:boolean}>();const data=ref<any>();const error=ref('');const notice=ref('');const busy=ref(false);const invoice=ref<any>();const topup=ref(false);const amount=ref(10);const currency=ref('USD');const promo=ref('');
const plans=computed(()=>{const map=new Map<string,Plan>();for(const p of data.value?.plans||[])if(!map.has(p.key)||map.get(p.key)!.version<p.version)map.set(p.key,p);return [...map.values()];});
async function load(){try{data.value=await api('/billing',{workspace:props.workspace});error.value='';}catch(e:any){error.value=e.message;}}
async function action(path:string,body:unknown){busy.value=true;try{const r=await api('/billing/'+path,{workspace:props.workspace,method:'POST',body});await load();return r;}finally{busy.value=false;}}
async function choose(p:Plan){try{const r=promo.value&&p.priceMinor?await action('invoices',{planId:p.id,promoCode:promo.value}):await action('change-plan',{planId:p.id});invoice.value=r.invoice||r.id&&r;notice.value=r.message||'Invoice created. No payment has been made.';}catch(e:any){error.value=e.message;}}
async function createCredits(){try{invoice.value=await action('invoices',{amountMinor:Math.round(amount.value*100),currency:currency.value});topup.value=false;}catch(e:any){error.value=e.message;}}
async function pay(gateway:string){try{const result=await action('checkout',{invoiceId:invoice.value.id,gateway});if(result.url){location.assign(result.url);return;}if(gateway==='razorpay'){if(!(window as any).Razorpay)await new Promise<void>((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=()=>resolve();script.onerror=()=>reject(new Error('Unable to load Razorpay checkout.'));document.head.appendChild(script);});new (window as any).Razorpay({key:result.keyId,order_id:result.orderId,amount:result.amount,currency:result.currency,name:data.value.billingLabel,description:'Sahdev invoice',handler:()=>{notice.value='Payment submitted. Access updates after the captured payment is verified.';load();}}).open();}}catch(e:any){error.value=e.message;}}
function printInvoice(){const blob=new Blob([JSON.stringify({merchant:data.value.billingLabel,invoice:invoice.value,notice:'Payment request. Tax invoice setup requires merchant configuration.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=invoice.value.id+'.json';a.click();URL.revokeObjectURL(url);}
onMounted(async()=>{await load();const url=new URL(location.href);if(url.searchParams.get('paypal_return')==='1'&&url.searchParams.get('token')){try{await action('paypal-capture',{orderId:url.searchParams.get('token')});notice.value='Payment capture checked.';}catch(e:any){error.value=e.message;}history.replaceState({},'',location.pathname+'#billing');}});
</script>
<template><div class="page-heading"><div><div class="greeting">CLEAR PLANS. NO HIDDEN TOKEN BILL.</div><h1>Room to grow, on your terms.</h1><p>Your subscription unlocks features. Prepaid credits fund hosted AI usage.</p></div><button class="button primary" @click="topup=true"><Icon name="plus" :size="16"/>Add prepaid credits</button></div><p v-if="error" class="form-error mb-4" role="alert">{{error}}</p><p v-if="notice" class="success-banner" role="status">{{notice}}</p><template v-if="data"><div class="billing-summary"><section class="panel current-plan"><span class="eyebrow">CURRENT PLAN</span><h2>{{data.plan.name}}<span :class="['status',data.subscription.state==='active'?'open':'pending']">{{data.subscription.state}}</span></h2><p>{{money(data.plan.priceMinor,data.plan.currency)}} per {{data.plan.intervalDays}} days</p><small>{{data.plan.priceMinor?'Paid period ends':'Free plan review date'}} {{new Date(data.subscription.period_end).toLocaleDateString('en-IN')}}</small><small v-if="data.subscription.pending_plan_id">Plan change scheduled at renewal.</small></section><section class="panel wallet-card"><span class="eyebrow">PREPAID AI BALANCE</span><div v-if="!data.wallets.length" class="wallet-balance">$0.00</div><div v-for="wallet in data.wallets" :key="wallet.currency" class="wallet-balance">{{money(wallet.balance/10000,wallet.currency)}}<small>{{money(wallet.reserved/10000,wallet.currency)}} reserved</small></div><p>BYOK calls do not spend this balance. Provider fees are paid directly to your provider.</p><span class="pill sample mt-3">No model calls while AI is disabled</span></section></div><div v-if="sample" class="info-box mb-5"><Icon name="help"/>This is a fictional sample workspace. Advanced configuration can be explored here; it does not grant a paid subscription or real AI credit.</div><div class="collection-toolbar no-border"><h2>Available plans</h2><div class="list-search"><Icon name="card" :size="16"/><input v-model="promo" placeholder="Promotion code (optional)" aria-label="Promotion code" @input="promo=promo.toUpperCase()"/></div></div><div class="plan-grid"><article v-for="p in plans" :key="p.id" class="panel plan-card"><h2>{{p.name}}</h2><p>{{p.description}}</p><div class="plan-price">{{money(p.priceMinor,p.currency)}}<span>/ {{p.intervalDays}} days</span></div><ul><li><Icon name="check" :size="14"/>{{p.limits.seats}} team members</li><li><Icon name="check" :size="14"/>{{p.limits.conversations.toLocaleString()}} conversations</li><li><Icon name="check" :size="14"/>{{p.limits.sources}} knowledge sources</li><li><Icon :name="p.features.byok?'check':'x'" :size="14"/>Bring your own AI key</li><li><Icon :name="p.features.memory?'check':'x'" :size="14"/>Optional customer memory</li></ul><button class="button" :class="data.plan.id===p.id?'secondary':'primary'" :disabled="data.plan.id===p.id||busy" @click="choose(p)">{{data.plan.id===p.id?'Your current plan':p.priceMinor?'Create plan invoice':'Switch to Free'}}</button></article></div><section class="panel mt-7"><div class="panel-heading mb-5"><div><h2>Invoices & payment requests</h2><p>Payment status is updated only after a verified provider event.</p></div></div><div class="table-scroll"><table><thead><tr><th>Invoice</th><th>Purpose</th><th>Amount</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="i in data.invoices" :key="i.id"><td class="mono">{{i.id.slice(0,12)}}</td><td>{{i.purpose==='credits'?'Prepaid AI credit':'Workspace plan'}}</td><td>{{money(i.amount,i.currency)}}</td><td><span :class="['status',i.state==='paid'?'open':'pending']">{{i.state}}</span></td><td>{{new Date(i.created_at).toLocaleDateString('en-IN')}}</td><td><button class="text-action" @click="invoice=i">View <Icon name="arrow" :size="13"/></button></td></tr><tr v-if="!data.invoices.length"><td class="table-empty" colspan="6">No invoices yet. Your Free plan does not require payment.</td></tr></tbody></table></div></section><section class="panel policy-note"><Icon name="shield"/><p>Prepaid plan periods activate after payment. Free downgrades take effect at the end of the current paid period. Automatic renewals are not enabled. Past-due paid workspaces become read-only after the configured grace period.</p></section></template><Modal :open="topup" @update:open="topup=$event" title="Prepay for hosted AI" description="Create a payment request. Your balance changes only after a confirmed payment."><form class="modal-form" @submit.prevent="createCredits"><div class="form-row"><label>Amount<input type="number" min="1" max="10000" step="0.01" v-model.number="amount" required/></label><label>Currency<select v-model="currency"><option>USD</option><option>INR</option></select></label></div><div class="info-box"><Icon name="help"/>Live AI is disabled. Credits should only be purchased after your provider and production payment integration have been validated.</div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button class="button secondary" type="button" @click="topup=false">Cancel</button><button class="button primary" :disabled="busy">Create invoice</button></div></form></Modal><Modal :open="!!invoice" @update:open="!$event&&(invoice=undefined)" title="Payment request" description="Review your invoice before opening the payment provider."><div v-if="invoice" class="invoice-detail"><div class="flex justify-between items-start"><div><strong>{{data.billingLabel}}</strong><small class="mono block muted mt-2">{{invoice.id}}</small></div><span :class="['status',invoice.state==='paid'?'open':'pending']">{{invoice.state}}</span></div><div class="invoice-total">{{money(invoice.amount,invoice.currency)}}</div><div class="invoice-row"><span>For</span><strong>{{invoice.purpose==='credits'?'Prepaid hosted AI credit':'Workspace plan period'}}</strong></div><div class="invoice-row"><span>Due</span><strong>{{new Date(invoice.due_at).toLocaleDateString('en-IN')}}</strong></div><p class="tiny-note my-5">This payment request is not a finalized tax invoice. Merchant tax details must be configured before public billing launch.</p><div v-if="invoice.state==='open'" class="gateway-buttons"><button v-for="g in ['stripe','paypal','razorpay']" :key="g" class="button secondary capitalize" :disabled="!data.gateways[g]||busy" @click="pay(g)">{{g}}<span v-if="!data.gateways[g]" class="muted">Not connected</span></button></div><button class="text-action mt-5" @click="printInvoice"><Icon name="download" :size="15"/>Download invoice record</button><p v-if="error" class="form-error mt-4">{{error}}</p></div></Modal></template>
